  Class<?> phone=Class.forName("local.tvmorph.tv.PhoneIptvActivity",true,context.getClassLoader());Method accounts=phone.getMethod("accounts",Context.class);String beforeAccounts=String.valueOf(accounts.invoke(null,context));
  main=startActivitySync(new Intent().setClassName(context.getPackageName(),context.getPackageName()+".MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Field field=main.getClass().getDeclaredField("web");field.setAccessible(true);web=(WebView)field.get(main);waitJS("window.MorphWorship&&window.Morph30");Thread.sleep(500);
