   JSONObject state=command(new JSONObject().put("operation","save").put("settings",config));check(state.getJSONArray("today").length()==6,"Six offline solar/prayer times are computed for the city");check(state.optBoolean("scheduled")&&state.optLong("nextAt")>System.currentTimeMillis(),"Actual exact-alarm scheduling produces a future prayer alarm");
