   config.put("enabled",false).put("reminders",true);state=command(new JSONObject().put("operation","save").put("settings",config));check(state.optBoolean("scheduled")&&!state.getJSONObject("settings").optBoolean("enabled"),"Prayer reminders can be enabled without full Adhan");
   long reminderAt=System.currentTimeMillis()+2300;context.getSharedPreferences("morph-faith-prayer",0).edit().putLong("nextAt",reminderAt).putInt("nextPrayer",0).commit();Class<?> reminderReceiver=Class.forName("local.cleartv.mobile.FaithAlarmReceiver",true,context.getClassLoader());PendingIntent reminderPending=PendingIntent.getBroadcast(context,7301,new Intent(context,reminderReceiver).setAction("local.cleartv.mobile.FAITH_ADHAN"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);context.getSystemService(AlarmManager.class).setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,reminderAt,reminderPending);runOnMainSync(()->main.moveTaskToBack(true));boolean reminded=false;for(int tries=0;tries<48&&!reminded;tries++){Thread.sleep(250);for(android.service.notification.StatusBarNotification notice:context.getSystemService(NotificationManager.class).getActiveNotifications())if(notice.getId()==7314)reminded=true;}check(reminded&&!playing(),"Real OS alarm shows prayer notification in background without starting Adhan");
   runOnMainSync(()->context.startActivity(new Intent(context,main.getClass()).addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT|Intent.FLAG_ACTIVITY_NEW_TASK)));Thread.sleep(300);config.put("enabled",true).put("reminders",false);command(new JSONObject().put("operation","save").put("settings",config));
   long at=System.currentTimeMillis()+2500;context.getSharedPreferences("morph-faith-prayer",0).edit().putLong("nextAt",at).putInt("nextPrayer",0).commit();Class<?> receiver=Class.forName("local.cleartv.mobile.FaithAlarmReceiver",true,context.getClassLoader());PendingIntent pending=PendingIntent.getBroadcast(context,7301,new Intent(context,receiver).setAction("local.cleartv.mobile.FAITH_ADHAN"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);context.getSystemService(AlarmManager.class).setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pending);runOnMainSync(()->main.moveTaskToBack(true));waitAudio(true);check(true,"OS alarm starts the adhan with the phone app in background");
   check(context.getSystemService(NotificationManager.class).getActiveNotifications().length>0,"Foreground adhan has a stop-capable notification");
   command(new JSONObject().put("operation","host").put("enabled",false));waitAudio(false);check(!((JSONObject)call("snapshot",new Class[]{Context.class},context)).optBoolean("scheduled"),"Hiding worship stops adhan and cancels its alarm");
   runOnMainSync(()->{Intent i=new Intent(context,main.getClass()).addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT|Intent.FLAG_ACTIVITY_NEW_TASK);context.startActivity(i);});Thread.sleep(500);
   command(new JSONObject().put("operation","host").put("enabled",true));
   Activity movie=startActivitySync(new Intent().setClassName(context.getPackageName(),"local.tvmorph.tv.PlayerActivity").putExtra("url","http://127.0.0.1:18991/phone291-playback-fixture.mp4").putExtra("name","Local faith audio fixture").putExtra("phone",true).putExtra("live",false).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Object video=field(movie,"video");waitVideo(video,true);command(new JSONObject().put("operation","preview").put("voice","egypt"));waitAudio(true);waitVideo(video,false);check(true,"Adhan pauses active phone IPTV playback");runOnMainSync(()->{movie.dispatchKeyEvent(new android.view.KeyEvent(android.view.KeyEvent.ACTION_DOWN,android.view.KeyEvent.KEYCODE_MEDIA_PLAY));movie.dispatchKeyEvent(new android.view.KeyEvent(android.view.KeyEvent.ACTION_UP,android.view.KeyEvent.KEYCODE_MEDIA_PLAY));});waitAudio(false);waitVideo(video,true);check(true,"Explicit Play stops Adhan and resumes IPTV");runOnMainSync(()->{movie.dispatchKeyEvent(new android.view.KeyEvent(android.view.KeyEvent.ACTION_DOWN,android.view.KeyEvent.KEYCODE_MEDIA_PAUSE));movie.dispatchKeyEvent(new android.view.KeyEvent(android.view.KeyEvent.ACTION_UP,android.view.KeyEvent.KEYCODE_MEDIA_PAUSE));});waitVideo(video,false);command(new JSONObject().put("operation","preview").put("voice","egypt"));waitAudio(true);command(new JSONObject().put("operation","stop"));waitAudio(false);check(!videoPlaying(video),"An already-paused video remains paused after Adhan");runOnMainSync(()->movie.finish());Thread.sleep(1500);
   js("Morph30.show('play');return true;");ActivityMonitor monitor=addMonitor(context.getPackageName()+".MatchesActivity",null,false);js("document.getElementById('phone-iptv-matches').click();return true;");Activity matches=monitor.waitForActivityWithTimeout(15000);check(matches!=null,"IPTV opens a complete native matches page");Field mf=matches.getClass().getDeclaredField("web");mf.setAccessible(true);WebView matchesWeb=(WebView)mf.get(matches);WebView hostWeb=web;web=matchesWeb;waitJS("document.querySelector('#page-matches .mp-hero')");check(true,"Native matches page has the new hero and themed schedule view");runOnMainSync(()->matches.finish());web=hostWeb;Thread.sleep(250);check(js("return document.body.dataset.mobilePage;").contains("page-iptv"),"Returning from Matches preserves the IPTV destination");removeMonitor(monitor);
   js("Morph30.show('worship');MorphWorship.back();MorphWorship.back();MorphAppearance.set('dark');return true;");waitForIdleSync();check(js("var r=document.querySelector('#page-worship'),c=r.querySelector('.wf-tile strong');return !r.hidden&&c&&getComputedStyle(r).getPropertyValue('--wf-surface').trim()==='#263952'&&getComputedStyle(c).color==='rgb(241, 246, 255)';").equals("true"),"Actual WebView dark cards keep explicit high-contrast colors");
